-- 10_ddl_v2.sql : membuat 10 tabel BARU di schema v2, berdampingan dengan tabel lama. Tidak menyentuh data lama.
BEGIN;

CREATE SCHEMA IF NOT EXISTS v2;

-- Master Pengguna & Hak Akses
CREATE TABLE v2."TWMSUsers" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Username" varchar(100) NOT NULL UNIQUE,
  "PasswordHash" varchar(255) NOT NULL,
  "FullName" varchar(255) NOT NULL,
  "Role" varchar(20) NOT NULL CHECK ("Role" IN ('ADMIN','OPERATOR','USER_SEKSI')),
  "SectionName" varchar(100),
  "Description" text,
  "IsActive" boolean NOT NULL DEFAULT true,
  "CreateDate" timestamptz DEFAULT now(),
  "UpdateBy" varchar(50),
  "UpdateDate" timestamptz DEFAULT now()
);

-- Master Unit Daisha
CREATE TABLE v2."TWMSDaishaCatalog" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UnitCode" varchar(50) NOT NULL UNIQUE,
  "SectionName" varchar(100),
  "DaishaType" varchar(150) NOT NULL,
  "UnitCategory" varchar(100),
  "SizeSpec" varchar(100),
  "CurrentCondition" varchar(20) DEFAULT 'OK',
  "LastPMDate" timestamptz,
  "IsActive" boolean NOT NULL DEFAULT true,
  "CreateDate" timestamptz DEFAULT now(),
  "UpdateBy" varchar(50),
  "UpdateDate" timestamptz DEFAULT now()
);

-- Katalog Komponen & Gejala Kerusakan
CREATE TABLE v2."TWMSDamageCatalog" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "DaishaType" varchar(150) NOT NULL,
  "SectionName" varchar(100),
  "ComponentName" varchar(150),
  "SymptomDesc" varchar(255),
  "UpdateBy" varchar(50),
  "UpdateDate" timestamptz DEFAULT now()
);

-- Transaksi Tiket Perbaikan Daisha
CREATE TABLE v2."TWMSRepairTicket" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TicketNo" varchar(50) NOT NULL UNIQUE,
  "UnitCode" varchar(50) NOT NULL,
  "ReporterName" varchar(255) NOT NULL,
  "ReporterSection" varchar(100),
  "DamageCategory" varchar(150),
  "DamageDescription" varchar(255),
  "UrgencyLevel" varchar(20),
  "PhotoPath" varchar(255),
  "Status" varchar(30) NOT NULL DEFAULT 'Open',
  "AssignedTech" varchar(50),
  "ActionTaken" text,
  "ReportDate" timestamptz DEFAULT now(),
  "StartRepairDate" timestamptz,
  "CompletedDate" timestamptz,
  "UpdateBy" varchar(50),
  "UpdateDate" timestamptz DEFAULT now()
);

-- Rincian Komponen pada Tiket
CREATE TABLE v2."TWMSRepairTicketDetail" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TicketId" int NOT NULL,
  "LineNo" int NOT NULL,
  "ComponentName" varchar(255),
  "SymptomDesc" varchar(255),
  "ActionType" varchar(30),
  "Qty" int NOT NULL DEFAULT 1,
  "DamageCatalogId" int
);

-- Pengajuan & Follow-Up Request Seksi
CREATE TABLE v2."TWMSSectionRequest" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RequestNo" varchar(100) NOT NULL UNIQUE,
  "NomorSurat" varchar(100),
  "RequestDate" timestamptz,
  "RequesterName" varchar(255),
  "RequesterContact" varchar(100),
  "RequesterSection" varchar(100),
  "CreatedBy" varchar(100),
  "RequestType" varchar(100),
  "Subject" text,
  "MachineName" text,
  "ItemTitle" text,
  "ItemSpec" text,
  "ItemQty" int,
  "ItemUnit" varchar(50),
  "ProblemFactor" varchar(100),
  "Reason" text,
  "Urgency" varchar(50),
  "Remark" text,
  "SectionCode" varchar(50),
  "Drafter" varchar(100),
  "Foreman" varchar(100),
  "CurrentCondition" text,
  "PhotoBefore" text,
  "ActionPlan" text,
  "PhotoAfter" text,
  "TargetResult" text,
  "ExecutionNote" text,
  "Decision" varchar(100),
  "Decision8210" varchar(100),
  "Decision820" varchar(100),
  "CheckResult" text,
  "CheckResultRequester" varchar(100),
  "SchedulePlan" text,
  "ScheduleActual" text,
  "PendingReason" text,
  "WorkflowStatus" varchar(100),
  "FlowStep" varchar(100),
  "ApprovalToken" varchar(100),
  "FinishDate" timestamptz,
  "SectionHeadName" varchar(255),
  "SectionHeadEmail" varchar(255),
  "SectionHeadStatus" varchar(50),
  "SectionHeadSignature" text,
  "WorkshopEmail" varchar(255),
  "WorkshopSignature" text,
  "SpecialProjectSignature" text,
  "EstCost" varchar(100),
  "EstManHour" varchar(100),
  "EstDuration" varchar(100),
  "EstExecDate" varchar(100),
  "EstComment" text,
  "ActCost" varchar(100),
  "ActManHour" varchar(100),
  "ActDuration" varchar(100),
  "ActExecDate" varchar(100),
  "ActComment" text,
  "UpdateBy" varchar(50),
  "UpdateDate" timestamptz DEFAULT now()
);

-- Kebutuhan Material pada Request
CREATE TABLE v2."TWMSSectionRequestMaterial" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RequestId" int NOT NULL,
  "SparepartId" int,
  "MaterialName" varchar(255) NOT NULL,
  "MaterialType" varchar(20) NOT NULL DEFAULT 'MATERIAL' CHECK ("MaterialType" IN ('SPAREPART','MATERIAL')),
  "MaterialSpec" varchar(100),
  "QtyUsed" numeric(12,2) NOT NULL DEFAULT 1,
  "Unit" varchar(50),
  "DeductStock" boolean NOT NULL DEFAULT false,
  "QtyDeducted" numeric(12,2) NOT NULL DEFAULT 0,
  "Remark" text
);

-- Transaksi Preventive Maintenance & Staging
CREATE TABLE v2."TWMSMaintenanceLog" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UnitCode" varchar(50) NOT NULL,
  "SectionName" varchar(100),
  "RecordType" varchar(10) NOT NULL CHECK ("RecordType" IN ('PM','STAGING')),
  "PeriodMonth" varchar(7),
  "StagingStatus" varchar(30),
  "StagingLocation" text,
  "ReporterName" varchar(255),
  "StagingDate" timestamptz,
  "PickedUpDate" timestamptz,
  "CompletedDate" timestamptz,
  "WorkType" varchar(100),
  "ChecklistResult" varchar(50),
  "InspectionNote" text,
  "ActionTaken" text,
  "CheckDate" timestamptz,
  "EntryTime" timestamptz,
  "ExitTime" timestamptz,
  "InspectorBy" varchar(100),
  "Notes" text,
  "UpdateDate" timestamptz DEFAULT now()
);

-- Master Inventaris Sparepart Bengkel
CREATE TABLE v2."TWMSSparepartMaster" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PartCode" varchar(30),
  "PartName" varchar(255) NOT NULL UNIQUE,
  "Category" varchar(100),
  "CurrentStock" int NOT NULL DEFAULT 0,
  "MinStock" int NOT NULL DEFAULT 0,
  "Unit" varchar(50) NOT NULL DEFAULT 'Pcs',
  "LocationRack" varchar(100),
  "UpdateBy" varchar(50),
  "UpdateDate" timestamptz DEFAULT now()
);

-- Riwayat Mutasi Stok Sparepart
CREATE TABLE v2."TWMSSparepartLog" (
  "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SparepartId" int,
  "PartName" varchar(255) NOT NULL,
  "MovementType" varchar(50),
  "Qty" int,
  "Notes" text,
  "TicketId" int,
  "MovementBy" varchar(100),
  "MovementDate" timestamptz DEFAULT now()
);

-- Foreign key
ALTER TABLE v2."TWMSRepairTicket" ADD CONSTRAINT fk_twmsrepairticket_unitcode FOREIGN KEY ("UnitCode") REFERENCES v2."TWMSDaishaCatalog" ("UnitCode");
ALTER TABLE v2."TWMSRepairTicketDetail" ADD CONSTRAINT fk_twmsrepairticketdetail_ticketid FOREIGN KEY ("TicketId") REFERENCES v2."TWMSRepairTicket" ("Id") ON DELETE CASCADE;
ALTER TABLE v2."TWMSRepairTicketDetail" ADD CONSTRAINT fk_twmsrepairticketdetail_damagecatalogid FOREIGN KEY ("DamageCatalogId") REFERENCES v2."TWMSDamageCatalog" ("Id");
ALTER TABLE v2."TWMSSectionRequestMaterial" ADD CONSTRAINT fk_twmssectionrequestmaterial_requestid FOREIGN KEY ("RequestId") REFERENCES v2."TWMSSectionRequest" ("Id") ON DELETE CASCADE;
ALTER TABLE v2."TWMSSectionRequestMaterial" ADD CONSTRAINT fk_twmssectionrequestmaterial_sparepartid FOREIGN KEY ("SparepartId") REFERENCES v2."TWMSSparepartMaster" ("Id");
ALTER TABLE v2."TWMSMaintenanceLog" ADD CONSTRAINT fk_twmsmaintenancelog_unitcode FOREIGN KEY ("UnitCode") REFERENCES v2."TWMSDaishaCatalog" ("UnitCode");
ALTER TABLE v2."TWMSSparepartLog" ADD CONSTRAINT fk_twmssparepartlog_sparepartid FOREIGN KEY ("SparepartId") REFERENCES v2."TWMSSparepartMaster" ("Id");
ALTER TABLE v2."TWMSSparepartLog" ADD CONSTRAINT fk_twmssparepartlog_ticketid FOREIGN KEY ("TicketId") REFERENCES v2."TWMSRepairTicket" ("Id");

-- Indeks
CREATE UNIQUE INDEX ux_twms_nomorsurat ON v2."TWMSSectionRequest" ("NomorSurat") WHERE "NomorSurat" IS NOT NULL;
CREATE UNIQUE INDEX ux_twms_partcode ON v2."TWMSSparepartMaster" ("PartCode") WHERE "PartCode" IS NOT NULL;
CREATE UNIQUE INDEX ux_twms_damagecatalog ON v2."TWMSDamageCatalog" (lower("DaishaType"), lower(coalesce("ComponentName", '')), lower(coalesce("SymptomDesc", '')));
CREATE INDEX ix_twms_users_section ON v2."TWMSUsers" ("SectionName");
CREATE INDEX ix_twms_unit_section ON v2."TWMSDaishaCatalog" ("SectionName");
CREATE INDEX ix_twms_unit_type ON v2."TWMSDaishaCatalog" (lower("DaishaType"));
CREATE INDEX ix_twms_ticket_unit ON v2."TWMSRepairTicket" ("UnitCode");
CREATE INDEX ix_twms_ticket_status ON v2."TWMSRepairTicket" ("Status");
CREATE INDEX ix_twms_ticket_report ON v2."TWMSRepairTicket" ("ReportDate");
CREATE INDEX ix_twms_ticketdetail_ticket ON v2."TWMSRepairTicketDetail" ("TicketId");
CREATE INDEX ix_twms_sr_status ON v2."TWMSSectionRequest" ("WorkflowStatus");
CREATE INDEX ix_twms_sr_section ON v2."TWMSSectionRequest" ("RequesterSection");
CREATE INDEX ix_twms_srm_request ON v2."TWMSSectionRequestMaterial" ("RequestId");
CREATE INDEX ix_twms_mlog_unit ON v2."TWMSMaintenanceLog" ("UnitCode");
CREATE INDEX ix_twms_mlog_type_date ON v2."TWMSMaintenanceLog" ("RecordType", "CheckDate");
CREATE INDEX ix_twms_splog_part ON v2."TWMSSparepartLog" ("SparepartId");

COMMIT;
